/**
 * The parts-library catalogue: what the Library panel lists. It is data, generated by
 * `scripts/library/generate_catalogue.py` from bd_warehouse and shipped with the app (`data/catalogue.json`,
 * meshes in `data/meshes.bin`). Pure: no DOM, no three.js (tests run in Node).
 */

/** A value of a build parameter, e.g. `size: "M6-1"`, `length: 20`, `simple: true`. */
export type ParamValue = string | number | boolean;

/** Where one class's preview mesh sits in `meshes.bin` (see `mesh.ts`). */
export interface CatalogueMesh {
  readonly offset: number;
  readonly vertices: number;
  readonly triangles: number;
  /** Triangle indices are uint32 (else uint16). */
  readonly wide: boolean;
}

/** The one example the catalogue ships for a class: what it was built with and what it looks like. */
export interface CataloguePreview {
  /** What the preview was built with (`{ size: "M6-1", length: 20 }`). Shown, so it is never mistaken for the user's choice. */
  readonly params: Readonly<Record<string, ParamValue>>;
  /** Bounding box in mm. */
  readonly size: readonly [number, number, number];
  /** Bounding-box centre in the library's own coordinates, mm. */
  readonly centre: readonly [number, number, number];
  /** Solids in the part (a threaded screw is many). */
  readonly solids: number;
  /** Named sub-parts and how many of each (`Roller: 12`); empty for a single solid. */
  readonly parts: Readonly<Record<string, number>>;
  readonly mesh: CatalogueMesh;
}

/** One thing a user may choose for a part, taken from the library's own standard tables. */
export type CatalogueOption =
  | {
      readonly name: string;
      readonly kind: 'choice';
      readonly choices: readonly (string | number)[];
    }
  | {
      readonly name: string;
      readonly kind: 'size';
      /** Standard sizes; by type when the sizes depend on the standard (`typeParam` names it). */
      readonly sizes: readonly string[] | Readonly<Record<string, readonly string[]>>;
      readonly typeParam?: string;
    }
  | {
      readonly name: string;
      readonly kind: 'flag';
      /** Labels for `true` and `false` (e.g. "No thread (simple)" / "With thread"). */
      readonly on: string;
      readonly off: string;
    }
  | {
      readonly name: string;
      readonly kind: 'number';
      /** What the preview used. */
      readonly default: number;
      readonly unit: string;
    };

/** "fastener_type" → "Fastener type". */
export function optionLabel(name: string): string {
  const t = name.replaceAll('_', ' ');
  return t.charAt(0).toUpperCase() + t.slice(1);
}

/** The sizes to offer: those of the chosen type, else of the type the preview was built with. */
export function sizesFor(
  option: Extract<CatalogueOption, { kind: 'size' }>,
  chosen: Readonly<Record<string, ParamValue>>,
  previewParams: Readonly<Record<string, ParamValue>>,
): readonly string[] {
  if (Array.isArray(option.sizes)) return option.sizes as readonly string[];
  const bySize = option.sizes as Readonly<Record<string, readonly string[]>>;
  const type = option.typeParam
    ? (chosen[option.typeParam] ?? previewParams[option.typeParam])
    : undefined;
  return (typeof type === 'string' ? bySize[type] : undefined) ?? Object.values(bySize)[0] ?? [];
}

export interface CatalogueClass {
  readonly module: string;
  readonly group: string;
  /** Cuts into an existing model (a hole, a slot) instead of adding a part. */
  readonly operation: boolean;
  /** Extra search words, English and Chinese. */
  readonly keywords: string;
  /** What the user may choose (standard types and sizes, fixed choices, free numbers). Missing = nothing. */
  readonly options?: readonly CatalogueOption[];
  /** Missing when the class cannot be previewed on its own. */
  readonly preview?: CataloguePreview;
}

export interface CatalogueGroup {
  readonly name: string;
  readonly operation: boolean;
  readonly classes: readonly string[];
}

export interface CatalogueModule {
  readonly id: string;
  readonly label: string;
  readonly groups: readonly CatalogueGroup[];
}

export interface Catalogue {
  readonly format: 1;
  readonly library: string;
  readonly libraryVersion: string;
  /** build123d the catalogue was generated with (missing in catalogues made before it was recorded). */
  readonly build123dVersion?: string;
  /** Date the catalogue was generated, `yyyy-mm-dd`. */
  readonly generated: string;
  readonly modules: readonly CatalogueModule[];
  readonly classes: Readonly<Record<string, CatalogueClass>>;
}

/** Checks the shape the app relies on; the file is ours, so this only catches a wrong or damaged one. */
export function parseCatalogue(json: unknown): Catalogue {
  if (typeof json !== 'object' || json === null)
    throw new Error('The parts catalogue is not an object');
  const o = json as Record<string, unknown>;
  if (o['format'] !== 1) throw new Error(`Unknown parts catalogue format: ${String(o['format'])}`);
  if (!Array.isArray(o['modules']) || typeof o['classes'] !== 'object' || o['classes'] === null) {
    throw new Error('The parts catalogue has no modules or classes');
  }
  if (typeof o['library'] !== 'string' || typeof o['libraryVersion'] !== 'string') {
    throw new Error('The parts catalogue does not say which library it is from');
  }
  return json as Catalogue;
}

/** "SocketHeadCapScrew" → "Socket Head Cap Screw"; "VSlotLinearRail" → "V Slot Linear Rail"; "ORing" → "O Ring". */
export function humanizeClassName(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2');
}

/** Every class name in the order the panel lists them (module, group, class). */
export function allClassNames(catalogue: Catalogue): string[] {
  return catalogue.modules.flatMap((m) => m.groups.flatMap((g) => [...g.classes]));
}

/** Label of the module a class is in (for the search text and result headings). */
export function moduleLabel(catalogue: Catalogue, id: string): string {
  return catalogue.modules.find((m) => m.id === id)?.label ?? id;
}

/** Lower-case text a search looks in: class name (also split into words), group, module and keywords. */
export function searchText(catalogue: Catalogue, name: string): string {
  const c = catalogue.classes[name];
  if (!c) return '';
  return [name, humanizeClassName(name), c.group, moduleLabel(catalogue, c.module), c.keywords]
    .join(' ')
    .toLowerCase();
}

/**
 * Classes matching a search, in list order. Every word must be found in the class name (also split into
 * words), its group, its module or its keywords, ignoring case: "seal" finds O-rings and capped bearings,
 * "螺絲" finds the screws. An empty search matches everything.
 */
export function searchClasses(catalogue: Catalogue, query: string): string[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  const all = allClassNames(catalogue);
  if (words.length === 0) return all;
  return all.filter((name) => {
    const text = searchText(catalogue, name);
    return words.every((w) => text.includes(w));
  });
}

function trimNumber(n: number): string {
  return String(Math.round(n * 100) / 100);
}

/** "22 × 22 × 7 mm". */
export function formatSize(size: readonly [number, number, number]): string {
  return `${size.map(trimNumber).join(' × ')} mm`;
}

/** "size M6-1, length 20, simple": what a preview was built with, for the detail card. */
export function formatParams(params: Readonly<Record<string, ParamValue>>): string {
  return Object.entries(params)
    .map(([k, v]) => {
      const key = k.replaceAll('_', ' ');
      return typeof v === 'boolean' ? (v ? key : `not ${key}`) : `${key} ${String(v)}`;
    })
    .join(', ');
}

/** "Roller ×12, OuterRace ×1": the named sub-parts of a preview. Empty for a single solid. */
export function formatParts(parts: Readonly<Record<string, number>>): string {
  return Object.entries(parts)
    .map(([name, n]) => `${name} ×${String(n)}`)
    .join(', ');
}
